using Microsoft.AspNetCore.Diagnostics;using Microsoft.AspNetCore.Mvc;namespace OrderService.Services;public class GlobalExceptionHandler(ILogger<GlobalExceptionHandler>l):IExceptionHandler{public async ValueTask<bool>TryHandleAsync(HttpContext c,Exception e,CancellationToken t){l.LogError(e,"Unhandled exception");var s=e is NotFoundException?404:e is BusinessException?400:500;c.Response.StatusCode=s;await c.Response.WriteAsJsonAsync(new ProblemDetails{Status=s,Title="Request failed",Detail=e.Message},t);return true;}}